import{_ as t,o as a,c as n,ag as o}from"./chunks/framework.ePeAWSvT.js";const p=JSON.parse('{"title":"Annotations","description":"Add notes, color codes, and tags to captured traffic entries in NectoProxy.","frontmatter":{"title":"Annotations","description":"Add notes, color codes, and tags to captured traffic entries in NectoProxy."},"headers":[],"relativePath":"features/annotations.md","filePath":"features/annotations.md","lastUpdated":1772297611000}'),i={name:"features/annotations.md"};function s(r,e,l,d,c,h){return a(),n("div",null,[...e[0]||(e[0]=[o(`<h1 id="annotations" tabindex="-1">Annotations <a class="header-anchor" href="#annotations" aria-label="Permalink to &quot;Annotations&quot;">​</a></h1><p>Annotations let you add <strong>text notes</strong>, <strong>color codes</strong>, and <strong>tags</strong> to any captured traffic entry in NectoProxy. Use annotations to mark important requests, leave context for yourself or teammates, organize findings during debugging sessions, and create a searchable record of your observations.</p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Every entry in the NectoProxy traffic list can be annotated with:</p><ul><li><strong>Text notes</strong> -- Free-form text describing your observation or findings</li><li><strong>Color coding</strong> -- A visual color applied to the traffic list row for quick identification</li><li><strong>Tags</strong> -- Short labels for categorization and filtering</li></ul><p>Annotations are non-destructive -- they add metadata to traffic entries without modifying the original request or response data.</p><h2 id="adding-annotations" tabindex="-1">Adding Annotations <a class="header-anchor" href="#adding-annotations" aria-label="Permalink to &quot;Adding Annotations&quot;">​</a></h2><h3 id="text-notes" tabindex="-1">Text Notes <a class="header-anchor" href="#text-notes" aria-label="Permalink to &quot;Text Notes&quot;">​</a></h3><p>Add a text note to any traffic entry:</p><ol><li>Select an entry in the traffic list</li><li>Open the <strong>Annotations</strong> panel (or right-click and select <strong>Add Annotation</strong>)</li><li>Type your note in the text field</li><li>Save the annotation</li></ol><p>Notes can be any length and support plain text. Use them to record observations, hypotheses, or action items.</p><details class="details custom-block"><summary>Example Notes</summary><table tabindex="0"><thead><tr><th>Entry</th><th>Note</th></tr></thead><tbody><tr><td><code>POST /api/auth/login</code></td><td>&quot;This request is sending credentials in plain text. Should use HTTPS.&quot;</td></tr><tr><td><code>GET /api/products?page=2</code></td><td>&quot;Response takes 3.2s -- investigate database query performance.&quot;</td></tr><tr><td><code>PUT /api/users/123</code></td><td>&quot;Returns 500 intermittently. Possibly a race condition with concurrent updates.&quot;</td></tr><tr><td><code>GET /static/bundle.js</code></td><td>&quot;Bundle is 2.4 MB -- needs code splitting.&quot;</td></tr></tbody></table></details><h3 id="color-coding" tabindex="-1">Color Coding <a class="header-anchor" href="#color-coding" aria-label="Permalink to &quot;Color Coding&quot;">​</a></h3><p>Apply a color to a traffic entry&#39;s row in the traffic list. The colored row stands out visually, making it easy to spot marked entries when scrolling through a long list.</p><p>Available colors:</p><table tabindex="0"><thead><tr><th>Color</th><th>Hex</th><th>Common Usage</th></tr></thead><tbody><tr><td><strong>Gray</strong></td><td><code>#9E9E9E</code></td><td>Neutral marking, low priority</td></tr><tr><td><strong>Red</strong></td><td><code>#F44336</code></td><td>Errors, bugs, critical issues</td></tr><tr><td><strong>Blue</strong></td><td><code>#2196F3</code></td><td>Informational, notable requests</td></tr><tr><td><strong>Green</strong></td><td><code>#4CAF50</code></td><td>Working correctly, verified good</td></tr><tr><td><strong>Yellow</strong></td><td><code>#FFEB3B</code></td><td>Warnings, needs attention</td></tr><tr><td><strong>Purple</strong></td><td><code>#9C27B0</code></td><td>Special cases, unique behavior</td></tr></tbody></table><p>To apply a color:</p><ol><li>Right-click on an entry in the traffic list</li><li>Select <strong>Set Color</strong> from the context menu</li><li>Choose a color from the palette</li></ol><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Establish a consistent color scheme within your team. For example, always use red for bugs, green for verified-correct behavior, yellow for items that need follow-up, and blue for informational observations. This makes annotated traffic lists readable at a glance by anyone on the team.</p></div><h3 id="tags" tabindex="-1">Tags <a class="header-anchor" href="#tags" aria-label="Permalink to &quot;Tags&quot;">​</a></h3><p>Tags are short text labels that you can attach to traffic entries for categorization. Unlike notes, tags are designed for quick filtering and grouping.</p><p><strong>Adding tags:</strong></p><ol><li>Select an entry</li><li>Open the Annotations panel</li><li>Type a tag name and press Enter</li><li>Multiple tags can be added to a single entry</li></ol><p><strong>Example tags:</strong></p><ul><li><code>bug</code> -- Known bug</li><li><code>slow</code> -- Performance issue</li><li><code>auth</code> -- Authentication-related</li><li><code>reviewed</code> -- Already reviewed</li><li><code>follow-up</code> -- Needs further investigation</li><li><code>production</code> -- From production environment</li><li><code>regression</code> -- Behavioral change from previous version</li></ul><h2 id="timestamps" tabindex="-1">Timestamps <a class="header-anchor" href="#timestamps" aria-label="Permalink to &quot;Timestamps&quot;">​</a></h2><p>Every annotation is automatically <strong>timestamped</strong> with the date and time it was created. This provides a chronological record of your observations during a debugging session.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[2025-01-15 10:32:45] This response started returning 500 after the deployment.</span></span>
<span class="line"><span>[2025-01-15 10:35:12] Confirmed: the error is in the database migration.</span></span>
<span class="line"><span>[2025-01-15 10:48:30] Fix deployed. Response now returns 200 correctly.</span></span></code></pre></div><p>Timestamps are particularly valuable when debugging time-sensitive issues or when annotating traffic over an extended session.</p><h2 id="searching-by-annotations" tabindex="-1">Searching by Annotations <a class="header-anchor" href="#searching-by-annotations" aria-label="Permalink to &quot;Searching by Annotations&quot;">​</a></h2><p>Annotations are <strong>fully searchable</strong> through NectoProxy&#39;s search functionality.</p><h3 id="search-by-note-content" tabindex="-1">Search by Note Content <a class="header-anchor" href="#search-by-note-content" aria-label="Permalink to &quot;Search by Note Content&quot;">​</a></h3><p>Type note text into the search bar to find entries with matching annotations:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Search: &quot;race condition&quot;</span></span>
<span class="line"><span>Results: All entries with annotations containing &quot;race condition&quot;</span></span></code></pre></div><h3 id="search-by-tag" tabindex="-1">Search by Tag <a class="header-anchor" href="#search-by-tag" aria-label="Permalink to &quot;Search by Tag&quot;">​</a></h3><p>Filter the traffic list by tag:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Filter: tag:bug</span></span>
<span class="line"><span>Results: All entries tagged with &quot;bug&quot;</span></span></code></pre></div><h3 id="search-by-color" tabindex="-1">Search by Color <a class="header-anchor" href="#search-by-color" aria-label="Permalink to &quot;Search by Color&quot;">​</a></h3><p>Filter by annotation color to see all entries marked with a specific color:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Filter: color:red</span></span>
<span class="line"><span>Results: All entries with a red color annotation</span></span></code></pre></div><h2 id="use-cases" tabindex="-1">Use Cases <a class="header-anchor" href="#use-cases" aria-label="Permalink to &quot;Use Cases&quot;">​</a></h2><h3 id="marking-important-requests-during-debugging" tabindex="-1">Marking Important Requests During Debugging <a class="header-anchor" href="#marking-important-requests-during-debugging" aria-label="Permalink to &quot;Marking Important Requests During Debugging&quot;">​</a></h3><p>When investigating an issue, you often encounter specific requests that are significant. Instead of trying to remember them or noting line numbers externally, annotate them directly:</p><ol><li>Find the request that triggers the bug</li><li>Color it <strong>red</strong> and add a note: &quot;This is the failing request&quot;</li><li>Find the last working request</li><li>Color it <strong>green</strong> and add a note: &quot;Last request before failure&quot;</li><li>Now you can easily navigate between the two marked entries</li></ol><h3 id="collaborative-debugging" tabindex="-1">Collaborative Debugging <a class="header-anchor" href="#collaborative-debugging" aria-label="Permalink to &quot;Collaborative Debugging&quot;">​</a></h3><p>When multiple team members are working on the same issue:</p><ol><li>Export a session with annotations included</li><li>Share it with your teammate</li><li>Your teammate can see your notes, color codes, and tags</li><li>They can add their own annotations to build a shared understanding</li></ol><h3 id="categorizing-findings-during-security-review" tabindex="-1">Categorizing Findings During Security Review <a class="header-anchor" href="#categorizing-findings-during-security-review" aria-label="Permalink to &quot;Categorizing Findings During Security Review&quot;">​</a></h3><p>Use annotations to organize findings from a security review:</p><ol><li>Review traffic entries one by one</li><li>Tag suspicious entries with <code>security</code> and color them <strong>red</strong></li><li>Add notes describing the specific concern</li><li>Tag reviewed entries with <code>reviewed</code> and color them <strong>green</strong></li><li>When finished, filter by <code>tag:security</code> to see all findings</li></ol><details class="details custom-block"><summary>Example: Security Review Annotation Workflow</summary><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#42  GET /api/admin/users      [red] [security]</span></span>
<span class="line"><span>     Note: &quot;No authentication check. Returns all user data including emails.&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>#67  POST /api/upload           [yellow] [security]</span></span>
<span class="line"><span>     Note: &quot;Accepts any file type. No size limit. Check for path traversal.&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>#91  GET /api/config            [red] [security] [critical]</span></span>
<span class="line"><span>     Note: &quot;Returns database credentials in response body.&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>#103 GET /api/products          [green] [reviewed]</span></span>
<span class="line"><span>     Note: &quot;Proper authentication, pagination, no sensitive data.&quot;</span></span></code></pre></div></details><h3 id="debugging-session-journal" tabindex="-1">Debugging Session Journal <a class="header-anchor" href="#debugging-session-journal" aria-label="Permalink to &quot;Debugging Session Journal&quot;">​</a></h3><p>Use annotations as a running journal during a debugging session:</p><ol><li>Start investigating an issue</li><li>As you discover relevant requests, annotate them with your findings</li><li>The timestamps create a chronological record</li><li>When you find the root cause, annotate the decisive request</li><li>The annotated session serves as documentation of your debugging process</li></ol><h3 id="performance-analysis" tabindex="-1">Performance Analysis <a class="header-anchor" href="#performance-analysis" aria-label="Permalink to &quot;Performance Analysis&quot;">​</a></h3><p>Mark slow requests for follow-up optimization:</p><ol><li>Sort the traffic list by duration</li><li>Tag the slowest requests with <code>slow</code></li><li>Color them <strong>yellow</strong></li><li>Add notes about why each one is slow (e.g., &quot;Large payload,&quot; &quot;Slow backend query,&quot; &quot;Unnecessary redirect chain&quot;)</li><li>Filter by <code>tag:slow</code> to see all performance issues in one place</li></ol><h2 id="managing-annotations" tabindex="-1">Managing Annotations <a class="header-anchor" href="#managing-annotations" aria-label="Permalink to &quot;Managing Annotations&quot;">​</a></h2><h3 id="editing-annotations" tabindex="-1">Editing Annotations <a class="header-anchor" href="#editing-annotations" aria-label="Permalink to &quot;Editing Annotations&quot;">​</a></h3><p>Click on an existing annotation to edit its text, change its color, or modify its tags. Changes are saved immediately.</p><h3 id="removing-annotations" tabindex="-1">Removing Annotations <a class="header-anchor" href="#removing-annotations" aria-label="Permalink to &quot;Removing Annotations&quot;">​</a></h3><p>To remove an annotation:</p><ol><li>Open the Annotations panel for the entry</li><li>Click the <strong>Remove</strong> button next to the annotation you want to delete</li><li>Confirm the deletion</li></ol><h3 id="annotations-in-exports" tabindex="-1">Annotations in Exports <a class="header-anchor" href="#annotations-in-exports" aria-label="Permalink to &quot;Annotations in Exports&quot;">​</a></h3><p>Annotations are preserved when exporting sessions. When you share a session with annotations, the recipient sees all your notes, colors, and tags intact.</p><hr><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Annotations are stored with the session data. They are preserved across NectoProxy restarts as long as the session data is retained.</p></div>`,67)])])}const u=t(i,[["render",s]]);export{p as __pageData,u as default};
